type dataForTmpl struct {
	CveID            string
	Cvsses           string
	Exploits         []models.Exploit
	Metasploits      []models.Metasploit
	Summary          string
	Mitigation       string
	PatchURLs        []string
	Confidences      models.Confidences
	Cwes             []models.CweDictEntry
	Alerts           []models.Alert
	Links            []string
	References       []models.Reference
	Packages         []string
